            // TODO API_TEST_START
            java.util.List<String> formats = net.coobird.thumbnailator.util.ThumbnailatorUtils.getSupportedOutputFormats();

            assert formats != null : "Supported output formats list should not be null";
            boolean supportsPng = formats.stream().anyMatch(f -> f.equalsIgnoreCase("png"));
